/* Resume Guest using SRET */
sret

/* Back to Host */
.align 2
.Lkvm_switch_return:
	SAVE_GUEST_GPRS

kvm_riscv_vcpu_swap_in_guest_state(vcpu);
guest_state_enter_irqoff();
/* ... sret/ecall to guest ... */
vcpu->arch.last_exit_cpu = vcpu->cpu;
guest_state_exit_irqoff();
kvm_riscv_vcpu_swap_in_host_state(vcpu);

preempt_disable();
/* ... AIA update, IRQ disable, IN_GUEST_MODE ... */
kvm_riscv_vcpu_enter_exit(vcpu, &trap);
vcpu->mode = OUTSIDE_GUEST_MODE;
/* ... */
preempt_enable();

static int wrs_insn(struct kvm_vcpu *vcpu, struct kvm_run *run, ulong insn)
{
	vcpu->stat.wrs_exit_stat++;
	kvm_vcpu_on_spin(vcpu, vcpu->arch.guest_context.sstatus & SR_SPP);
	return KVM_INSN_CONTINUE_NEXT_SEPC;
}

case EXC_VIRTUAL_INST_FAULT:
	if (vcpu->arch.guest_context.hstatus & HSTATUS_SPV)
		ret = kvm_riscv_vcpu_virtual_insn(vcpu, run, trap);
	break;
/* No LR/SC-specific trap handling needed */

WRITE_ONCE(vcpu->scheduled_out, true);
if (task_is_runnable(current) && vcpu->wants_to_run) {
	WRITE_ONCE(vcpu->preempted, true);
	WRITE_ONCE(vcpu->ready, true);
}
kvm_arch_vcpu_put(vcpu);
